<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Payment extends Model{protected $fillable=['tenant_id','amount','paid_at','period','billing_cycle','period_count','method','recorded_by','is_historical','coverage_start','coverage_end','import_batch_id'];protected $casts=['paid_at'=>'date','coverage_start'=>'date','coverage_end'=>'date','amount'=>'decimal:2','period_count'=>'integer','is_historical'=>'boolean'];public function tenant(){return $this->belongsTo(Tenant::class);}public function recorder(){return $this->belongsTo(User::class,'recorded_by');}public function importBatch(){return $this->belongsTo(ImportBatch::class);}}
